use std::{env,path::PathBuf,process::Command};
fn main(){let out=PathBuf::from(env::var("OUT_DIR").unwrap());let obj=out.join("rail8.o");assert!(Command::new("gcc").args(["-O3","-march=native","-std=c11","-fPIC","-Wall","-Wextra","-c","rail8.c","-o"]).arg(&obj).status().unwrap().success());assert!(Command::new("ar").arg("crs").arg(out.join("librail8.a")).arg(obj).status().unwrap().success());println!("cargo:rustc-link-search=native={}",out.display());println!("cargo:rustc-link-lib=static=rail8");println!("cargo:rerun-if-changed=rail8.c");println!("cargo:rerun-if-changed=rail8.h");}
